    w,h=int(p[0]),int(p[1])
    raw=subprocess.run(['ffmpeg','-v','error','-i',f,'-f','rawvideo','-pix_fmt','rgba','-'],capture_output=True).stdout
    return w,h,raw
def frame(img,idx):
    w,h,raw=img; cols=w//32
    fx,fy=(idx%cols)*32,(idx//cols)*32
    return [tuple(raw[((fy+y)*w+fx+x)*4:((fy+y)*w+fx+x)*4+4]) for y in range(32) for x in range(32)]
def bbox(fr):
    pts=[(i%32,i//32) for i,p in enumerate(fr) if p[3]>0]
    if not pts: return None
    return (min(p[0] for p in pts),min(p[1] for p in pts),max(p[0] for p in pts),max(p[1] for p in pts))
